/**
 * The file kept across the reload that isolates the page.
 *
 * A `.blend` dropped on a page that is not yet isolated cannot be converted
 * there. The model and the files beside it are stashed in the import store
 * under a fixed address, the page reloads itself isolated, and the import
 * entry takes them back once and goes on. Taking is removing: a second boot
 * finds nothing and imports nothing.
 */
import { IMPORT_PREFIX, type FileStore } from './worldInMemory';
import type { ImportFile } from './importFiles';

export interface PendingStore extends Pick<FileStore, 'put' | 'delete'> {
  get(url: string): Promise<Uint8Array | null>;
}

export interface PendingImport {
  model: ImportFile;
  sidecars: Map<string, Uint8Array>;
}

/**
 * A world converted on the isolated page, handed to the ordinary page that
 * replaces it: the staged document's address, what the card says, and where
 * each file of the folder is, so the save can read them back. The files stay
 * staged; only this note is taken.
 */
export interface OpenedWorld {
  documentUrl: string;
  title: string;
  modelName: string;
  lines: string[];
  files: Array<{ path: string; url: string }>;
}

const openedUrl = (scopeUrl: string): string => new URL(`${IMPORT_PREFIX}pending/opened.json`, scopeUrl).href;

export async function stashOpenedWorld(store: PendingStore, scopeUrl: string, opened: OpenedWorld): Promise<void> {
  await store.put(openedUrl(scopeUrl), new TextEncoder().encode(JSON.stringify(opened)), 'application/json');
}

export async function takeOpenedWorld(store: PendingStore, scopeUrl: string): Promise<OpenedWorld | null> {
  const raw = await store.get(openedUrl(scopeUrl));
  if (!raw) return null;
  await store.delete(openedUrl(scopeUrl));
  return JSON.parse(new TextDecoder().decode(raw)) as OpenedWorld;
}

const manifestUrl = (scopeUrl: string): string => new URL(`${IMPORT_PREFIX}pending/manifest.json`, scopeUrl).href;
const fileUrl = (scopeUrl: string, name: string): string => new URL(`${IMPORT_PREFIX}pending/files/${encodeURIComponent(name)}`, scopeUrl).href;

export async function stashPendingImport(store: PendingStore, scopeUrl: string, model: ImportFile, sidecars: ReadonlyMap<string, Uint8Array>): Promise<void> {
  await store.put(fileUrl(scopeUrl, model.name), model.bytes, 'application/octet-stream');
  for (const [name, bytes] of sidecars) await store.put(fileUrl(scopeUrl, name), bytes, 'application/octet-stream');
  const manifest = { model: model.name, sidecars: [...sidecars.keys()] };
  await store.put(manifestUrl(scopeUrl), new TextEncoder().encode(JSON.stringify(manifest)), 'application/json');
}

export async function takePendingImport(store: PendingStore, scopeUrl: string): Promise<PendingImport | null> {
  const raw = await store.get(manifestUrl(scopeUrl));
  if (!raw) return null;
  const manifest = JSON.parse(new TextDecoder().decode(raw)) as { model: string; sidecars: string[] };
  const modelBytes = await store.get(fileUrl(scopeUrl, manifest.model));
  const sidecars = new Map<string, Uint8Array>();
  for (const name of manifest.sidecars) {
    const b = await store.get(fileUrl(scopeUrl, name));
    if (b) sidecars.set(name, b);
  }
  await store.delete(manifestUrl(scopeUrl));
  await store.delete(fileUrl(scopeUrl, manifest.model));
  for (const name of manifest.sidecars) await store.delete(fileUrl(scopeUrl, name));
  if (!modelBytes) return null;
  return { model: { name: manifest.model, bytes: modelBytes }, sidecars };
}
