/**
 * What the page says while Blender converts a file.
 *
 * The work has three steps, and the first can take a minute on a first
 * visit: Blender itself is loaded (about 36 MB, kept by the browser after
 * that), it starts, and it converts the file. A visitor watching has to be
 * able to tell which step this is and whether it is still moving, so every
 * line set says the step it is on, and when nothing new has been said for
 * thirty seconds a plain line says that too.
 *
 * Pure: no DOM, and the clock is handed in.
 */

/** A step of the work, with what is known of how far along it is. */
export type BlendStage =
  | { step: 'loading'; loaded?: number; total?: number }
  | { step: 'preparing' }
  | { step: 'starting' }
  | { step: 'converting'; file: string; tail: readonly string[] };

/** How long nothing may change before the page says so, in ms. */
export const QUIET_AFTER_MS = 30_000;

/**
 * How the card is laid out in a window opened only to convert: across the
 * window, which is small, so its lines wrap less; no taller than it; and
 * when Blender's own account of a failure is longer than that, scrolled
 * inside the card with a thin bar. The page's own corner card is narrower
 * than such a window and would run off its top. The client's own menu
 * button is put away: there is no world in such a window for it to set.
 */
export const CONVERTER_WINDOW_CSS =
  'html [data-webverse-import]{left:12px;right:12px;bottom:12px;width:auto;max-height:calc(100vh - 24px);' +
  'overflow-x:hidden;overflow-y:auto;scrollbar-width:thin;scrollbar-color:rgba(255,255,255,.35) transparent}' +
  'html [data-webverse-menu-button]{display:none!important}';

const megabytes = (bytes: number): string => `${(bytes / (1024 * 1024)).toFixed(1)} MB`;

/** The lines for `stage`, with a last line saying so when nothing has changed for `quietMs`. */
export function blendStageLines(stage: BlendStage, quietMs: number): string[] {
  const lines: string[] = [];
  if (stage.step === 'loading') {
    const far =
      stage.loaded === undefined ? '' : stage.total ? `, ${Math.round((100 * stage.loaded) / stage.total)}%` : `, ${megabytes(stage.loaded)} so far`;
    lines.push(`Step 1 of 3: loading Blender${far}.`, 'About 36 MB, the first time only. Your browser keeps it after that.');
  } else if (stage.step === 'converting') {
    lines.push(`Step 3 of 3: converting ${stage.file}.`, 'Blender is working through the scene. Nothing is uploaded.', ...stage.tail.slice(-2));
  } else {
    lines.push('Step 2 of 3: starting Blender.');
  }
  if (quietMs >= QUIET_AFTER_MS) {
    lines.push(
      `Nothing has changed for ${Math.floor(quietMs / 1000)} seconds. It may still be working: a large file can take a few minutes. If it stays like this, close this window and open the file again.`,
    );
  }
  return lines;
}

/** The clock a reporter runs on: the time in ms, and a call every so often with a way to stop it. */
export interface StageClock {
  now(): number;
  every(ms: number, run: () => void): () => void;
}

/** How often a reporter looks at whether anything has changed, in ms. */
const LOOK_EVERY_MS = 5_000;

export interface StageReporter {
  /** The work is at `stage` now. Shown at once; counted as movement only when it says something new. */
  set(stage: BlendStage): void;
  /** The work is over, either way: nothing more is shown. */
  stop(): void;
}

/**
 * Shows each stage through `show`, and shows it again with the quiet line
 * once nothing new has been set for thirty seconds.
 */
export function stageReporter(show: (lines: string[]) => void, clock: StageClock): StageReporter {
  let current: BlendStage | null = null;
  let said = '';
  let movedAt = clock.now();
  let stopLooking: (() => void) | null = clock.every(LOOK_EVERY_MS, () => {
    if (current === null) return;
    const quiet = clock.now() - movedAt;
    if (quiet >= QUIET_AFTER_MS) show(blendStageLines(current, quiet));
  });
  return {
    set(stage) {
      if (stopLooking === null) return;
      const lines = blendStageLines(stage, 0);
      const saying = lines.join('\n');
      current = stage;
      if (saying === said) return;
      said = saying;
      movedAt = clock.now();
      show(lines);
    },
    stop() {
      stopLooking?.();
      stopLooking = null;
      current = null;
    },
  };
}
